"""Encode and decode fixed-length EBCDIC records (DISPLAY text, zoned, packed and binary)."""

from __future__ import annotations

from decimal import Decimal
from typing import Any, Dict, List

from .copybook import Field, Layout

CODEPAGE = "cp037"
EBCDIC_SPACE = b"\x40"
_POSITIVE = {0xA, 0xC, 0xE, 0xF}
_NEGATIVE = {0xB, 0xD}


class CodecError(ValueError):
    """Raised when a value cannot be encoded, or bytes cannot be decoded, for a field."""


def _quantum(field: Field) -> Decimal:
    return Decimal(1).scaleb(-field.scale)


def _digit_string(field: Field, value: Any) -> str:
    number = Decimal(value)
    if number < 0 and not field.signed:
        raise CodecError(f"{field.name}: negative value {number} for an unsigned field")
    scaled = abs(number) * (Decimal(10) ** field.scale)
    if scaled != scaled.to_integral_value():
        raise CodecError(f"{field.name}: {number} has more than {field.scale} decimal places")
    digits = str(int(scaled))
    if len(digits) > field.total_digits:
        raise CodecError(f"{field.name}: {number} does not fit {field.describe()}")
    return digits.zfill(field.total_digits)


def encode_item(field: Field, value: Any) -> bytes:
    """Encode one occurrence of a field."""
    if field.kind == "X":
        text = "" if value is None else str(value)
        if len(text) > field.item_length:
            raise CodecError(f"{field.name}: {text!r} is longer than {field.item_length}")
        try:
            return text.ljust(field.item_length).encode(CODEPAGE)
        except UnicodeEncodeError as exc:
            raise CodecError(f"{field.name}: {text!r} has characters outside {CODEPAGE}") from exc

    if value is None:
        value = 0
    negative = Decimal(value) < 0
    digits = _digit_string(field, value)
    if field.kind == "9":
        out = bytearray(0xF0 | int(d) for d in digits)
        if field.signed:
            out[-1] = (0xD0 if negative else 0xC0) | int(digits[-1])
        return bytes(out)
    if field.kind == "B":
        number = -int(digits) if negative else int(digits)
        order = "little" if field.little_endian else "big"
        try:
            return number.to_bytes(field.item_length, order, signed=field.signed)
        except OverflowError as exc:
            raise CodecError(f"{field.name}: {value} does not fit {field.item_length} bytes") from exc

    sign =0xD if negative else (0xC if field.signed else 0xF)
    nibbles = [int(d) for d in digits] + [sign]
    if len(nibbles) % 2:
        nibbles.insert(0, 0)
    return bytes((nibbles[i] << 4) | nibbles[i + 1] for i in range(0, len(nibbles), 2))


def decode_item(field: Field, data: bytes) -> Any:
    """Decode one occurrence of a field. Numeric values come back as Decimal."""
    if field.kind == "X":
        return data.decode(CODEPAGE)

    negative = False
    if field.kind == "B":
        order = "little" if field.little_endian else "big"
        number = int.from_bytes(data, order, signed=field.signed)
        value = Decimal(number).scaleb(-field.scale).quantize(_quantum(field))
        return value if number else abs(value)
    if field.kind == "9":
        digits = []
        for index, byte in enumerate(data):
            zone, digit = byte >> 4, byte & 0xF
            if digit > 9:
                raise CodecError(f"{field.name}: invalid zoned digit 0x{byte:02X}")
            if index == len(data) - 1 and field.signed:
                if zone in _NEGATIVE:
                    negative = True
                elif zone not in _POSITIVE:
                    raise CodecError(f"{field.name}: invalid sign zone 0x{byte:02X}")
            elif zone != 0xF:
                raise CodecError(f"{field.name}: invalid zoned byte 0x{byte:02X}")
            digits.append(digit)
    else:
        nibbles: List[int] = []
        for byte in data:
            nibbles.extend((byte >> 4, byte & 0xF))
        sign = nibbles.pop()
        if any(n > 9 for n in nibbles):
            raise CodecError(f"{field.name}: invalid packed digit in {data.hex().upper()}")
        if sign in _NEGATIVE:
            negative = True
        elif sign not in _POSITIVE:
            raise CodecError(f"{field.name}: invalid packed sign nibble 0x{sign:X}")
        digits = nibbles

    number = int("".join(str(d) for d in digits) or "0")
    value = Decimal(number).scaleb(-field.scale).quantize(_quantum(field))
    return -value if negative and number else value


def _items(field: Field, value: Any) -> List[Any]:
    if field.occurs == 1:
        return [value]
    values = list(value or [])
    if len(values) > field.occurs:
        raise CodecError(f"{field.name}: {len(values)} items for OCCURS {field.occurs}")
    return values + [None] * (field.occurs - len(values))


def encode_record(layout: Layout, record: Dict[str, Any]) -> bytes:
    """Encode a record dict into one fixed-length EBCDIC record."""
    unknown = set(record) - set(layout.names())
    if unknown:
        raise CodecError(f"Unknown fields: {sorted(unknown)}")
    buffer = bytearray(EBCDIC_SPACE * layout.record_length)
    for field in layout.fields:
        for index, item in enumerate(_items(field, record.get(field.name))):
            start = field.offset + index * field.item_length
            buffer[start : start + field.item_length] = encode_item(field, item)
    return bytes(buffer)


def decode_record(layout: Layout, data: bytes) -> Dict[str, Any]:
    """Decode one fixed-length record into a dict of field name -> value (or list)."""
    if len(data) != layout.record_length:
        raise CodecError(f"Record is {len(data)} bytes, layout expects {layout.record_length}")
    record: Dict[str, Any] = {}
    for field in layout.fields:
        if field.offset < 0 or field.offset + field.length > len(data):
            raise CodecError(f"{field.name}: field extends outside the record")
        items = [
            decode_item(field, data[start : start + field.item_length])
            for start in range(field.offset, field.offset + field.length, field.item_length)
        ]
        record[field.name] = items if field.occurs > 1 else items[0]
    return record


def split_records(layout: Layout, data: bytes) -> List[bytes]:
    """Split a fixed-block (RECFM=F) file into records."""
    size = layout.record_length
    if len(data) % size:
        raise CodecError(f"File size {len(data)} is not a multiple of record length {size}")
    return [data[i : i + size] for i in range(0, len(data), size)]

"""Mapping specifications: how each source record becomes a target JSON document.

A mapping is a YAML file::

    name: claim-header
    key: R1                              # rule that identifies a document
    filter: {field: REC-TYPE, equals: D} # records that are loaded at all
    rules:
      - id: R1
        source: CLAIM-ID                 # copybook field
        target: claimId                  # dotted JSON path in the output document
        steps: [strip]                   # ordered transformations
        checks: [required, {pattern: '^C[0-9]+$'}]   # validations on the result
        on_error: reject                 # invalid input -> reject record (default: fail)

      - id: R9
        source: [FIRST-NAME, LAST-NAME]  # concatenation
        separator: " "
        target: member.fullName

      - id: R10
        value: MEDICAID                  # constant
        target: sourceSystem

      - id: R11
        source: ADMIT-DATE
        when: {field: CLAIM-TYPE, equals: IP}   # conditional mapping
        else: null
        target: admission.date
        steps: [{date: {in: "%Y%m%d", out: "%Y-%m-%d", nulls: ["00000000"]}}]

This module also holds the reference implementation of the mapping, which is
what WitnessForge treats as the specification of correct behaviour.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, replace
from datetime import datetime
from decimal import ROUND_HALF_UP, Decimal
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

import yaml

from .copybook import Field, Layout

PUBLIC_STEPS = {
    "strip", "rstrip", "lstrip", "upper", "lower", "number", "null_if_blank", "date", "map",
    "default", "substring", "lstrip_zeros", "pad", "boolean", "multiply", "divide", "round",
    "replace",
}
CHECKS = {
    "required", "min_length", "max_length", "min", "max", "pattern", "allowed",
    "min_items", "max_items", "unique_items", "unique",
}
ARRAY_CHECKS = {"min_items", "max_items", "unique_items"}
CONDITION_OPS = ("equals", "in", "not_blank", "blank")
REJECTED = "__rejected__"
FILTERED = "__filtered__"

Step = Tuple[str, Any]


class MappingError(ValueError):
    """Raised for an invalid mapping specification or a failing transformation."""


@dataclass(frozen=True)
class Condition:
    field: str
    op: str
    values: Tuple[Any, ...] = ()
    negate: bool = False  # set only by mutants

    def describe(self) -> str:
        text = {
            "equals": f"{self.field} = {self.values[0]!r}" if self.values else self.field,
            "in": f"{self.field} in {list(self.values)}",
            "not_blank": f"{self.field} is not blank",
            "blank": f"{self.field} is blank",
        }[self.op]
        return f"NOT ({text})" if self.negate else text


@dataclass(frozen=True)
class Rule:
    id: str
    target: str
    sources: Tuple[str, ...] = ()
    steps: Tuple[Step, ...] = ()
    checks: Tuple[Step, ...] = ()
    drop_blank: bool = False
    value: Any = None  # constant, used when there are no sources
    separator: str = ""
    trim_parts: bool = True
    when: Optional[Condition] = None
    when_else: Any = None
    on_error: str = "fail"  # fail | reject   ("null" is used only by mutants)
    distinct: bool = False  # remove duplicate array items
    items: Tuple[Tuple[str, "Rule"], ...] = ()  # array of objects from parallel OCCURS fields
    shift: int = 0  # set only by mutants: read element i+shift (misaligned OCCURS)
    array_op: Optional[str] = None  # set only by mutants
    parts_op: Optional[str] = None  # set only by mutants

    @property
    def source(self) -> Optional[str]:
        return self.sources[0] if len(self.sources) == 1 else None

    @property
    def is_constant(self) -> bool:
        return not self.sources and not self.items

    @property
    def all_sources(self) -> Tuple[str, ...]:
        """Every copybook field this rule reads (including object-array members)."""
        if self.items:
            return tuple(sub.source for _, sub in self.items)
        return self.sources

    def with_item(self, name: str, sub: "Rule") -> "Rule":
        return replace(self, items=tuple((n, sub if n == name else r) for n, r in self.items))

    @property
    def is_concat(self) -> bool:
        return len(self.sources) > 1


@dataclass(frozen=True)
class Mapping:
    name: str
    rules: Tuple[Rule, ...]
    key: Optional[str] = None  # id of the rule whose output identifies a document
    filter: Optional[Condition] = None

    @property
    def key_rule(self) -> Optional[Rule]:
        return self.rule(self.key) if self.key else None

    def rule(self, rule_id: str) -> Rule:
        for rule in self.rules:
            if rule.id == rule_id:
                return rule
        raise KeyError(rule_id)

    def with_rule(self, new_rule: Rule) -> "Mapping":
        return replace(
            self, rules=tuple(new_rule if r.id == new_rule.id else r for r in self.rules)
        )


# --------------------------------------------------------------------------- parsing


def _one_key(rule_id: str, raw: Any, what: str) -> Tuple[str, Any]:
    if isinstance(raw, str):
        return raw, None
    if isinstance(raw, dict) and len(raw) == 1:
        return next(iter(raw.items()))
    raise MappingError(f"{rule_id}: each {what} must be a name or a one-key mapping, got {raw!r}")


def _normalize_step(rule_id: str, raw: Any) -> Step:
    op, arg = _one_key(rule_id, raw, "step")
    if op not in PUBLIC_STEPS:
        raise MappingError(f"{rule_id}: unknown step {op!r} (known: {sorted(PUBLIC_STEPS)})")
    if op == "date":
        if not (isinstance(arg, dict) and "in" in arg and "out" in arg):
            raise MappingError(f"{rule_id}: date step needs 'in' and 'out' formats")
        arg = {"in": arg["in"], "out": arg["out"], "nulls": [str(n) for n in arg.get("nulls") or []]}
    elif op == "map":
        if not (isinstance(arg, dict) and isinstance(arg.get("values"), dict)):
            raise MappingError(f"{rule_id}: map step needs a 'values' dictionary")
        arg = {"values": {str(k): v for k, v in arg["values"].items()}, "default": arg.get("default")}
    elif op == "substring":
        if not (isinstance(arg, dict) and int(arg.get("start", 0)) >= 1 and int(arg.get("length", 0)) >= 1):
            raise MappingError(f"{rule_id}: substring needs start >= 1 and length >= 1")
        arg = {"start": int(arg["start"]), "length": int(arg["length"])}
    elif op == "pad":
        if not (isinstance(arg, dict) and int(arg.get("length", 0)) >= 1):
            raise MappingError(f"{rule_id}: pad needs a length")
        side = arg.get("side", "left")
        char = str(arg.get("char", " "))
        if side not in ("left", "right") or len(char) != 1:
            raise MappingError(f"{rule_id}: pad side must be left/right and char one character")
        arg = {"length": int(arg["length"]), "char": char, "side": side}
    elif op == "boolean":
        if isinstance(arg, dict):  # YAML reads the keys true/false as booleans
            arg = {str(k).lower(): v for k, v in arg.items()}
        if not (isinstance(arg, dict) and arg.get("true") and arg.get("false")):
            raise MappingError(f"{rule_id}: boolean needs 'true' and 'false' value lists")
        arg = {
            "true": [str(v) for v in _as_list(arg["true"])],
            "false": [str(v) for v in _as_list(arg["false"])],
            "default": arg.get("default"),
        }
    elif op in ("multiply", "divide"):
        try:
            arg = Decimal(str(arg))
        except Exception as exc:
            raise MappingError(f"{rule_id}: {op} needs a number") from exc
        if op == "divide" and arg == 0:
            raise MappingError(f"{rule_id}: divide by zero")
    elif op == "round":
        if not isinstance(arg, int) or arg < 0:
            raise MappingError(f"{rule_id}: round needs a number of decimal places")
    elif op == "replace":
        if not (isinstance(arg, dict) and "pattern" in arg):
            raise MappingError(f"{rule_id}: replace needs 'pattern' (and 'with')")
        _compile(rule_id, arg["pattern"])
        arg = {"pattern": arg["pattern"], "with": str(arg.get("with", ""))}
    return op, arg


def _normalize_check(rule_id: str, raw: Any) -> Step:
    op, arg = _one_key(rule_id, raw, "check")
    if op not in CHECKS:
        raise MappingError(f"{rule_id}: unknown check {op!r} (known: {sorted(CHECKS)})")
    if op in ("required", "unique_items", "unique"):
        return op, None
    if op in ("min_length", "max_length", "min_items", "max_items"):
        if not isinstance(arg, int) or arg < 0:
            raise MappingError(f"{rule_id}: {op} needs a non-negative integer")
    elif op in ("min", "max"):
        try:
            arg = Decimal(str(arg))
        except Exception as exc:
            raise MappingError(f"{rule_id}: {op} needs a number") from exc
    elif op == "pattern":
        _compile(rule_id, arg)
    elif op == "allowed":
        if not isinstance(arg, list) or not arg:
            raise MappingError(f"{rule_id}: allowed needs a non-empty list")
        arg = tuple(arg)
    return op, arg


def _compile(rule_id: str, pattern: Any) -> None:
    try:
        re.compile(str(pattern))
    except re.error as exc:
        raise MappingError(f"{rule_id}: invalid regular expression {pattern!r}: {exc}") from exc


def _as_list(value: Any) -> List[Any]:
    return list(value) if isinstance(value, (list, tuple)) else [value]


def _condition(owner: str, raw: Any, layout: Optional[Layout]) -> Condition:
    if not isinstance(raw, dict) or "field" not in raw:
        raise MappingError(f"{owner}: a condition needs 'field' and one of {CONDITION_OPS}")
    ops = [op for op in CONDITION_OPS if op in raw]
    if len(ops) != 1:
        raise MappingError(f"{owner}: a condition needs exactly one of {CONDITION_OPS}")
    field_name = str(raw["field"]).upper()
    if layout is not None:
        if field_name not in layout.names():
            raise MappingError(f"{owner}: condition field {field_name} is not in the copybook")
        if layout.field(field_name).occurs > 1:
            raise MappingError(f"{owner}: condition field {field_name} cannot be an OCCURS field")
    op = ops[0]
    values: Tuple[Any, ...] = ()
    if op == "equals":
        values = (raw["equals"],)
    elif op == "in":
        values = tuple(_as_list(raw["in"]))
    return Condition(field=field_name, op=op, values=values)


def _parse_items(rule_id: str, target: str, raw: Any, layout: Optional[Layout]):
    if not isinstance(raw, dict) or not raw:
        raise MappingError(f"{rule_id}: 'items' must map object keys to source fields")
    items = []
    occurs = set()
    for name, spec in raw.items():
        if isinstance(spec, str):
            spec = {"source": spec}
        if not isinstance(spec, dict) or not spec.get("source"):
            raise MappingError(f"{rule_id}.{name}: needs a 'source' field")
        source = str(spec["source"]).upper()
        sub_id = f"{rule_id}.{name}"
        if layout is not None:
            if source not in layout.names():
                raise MappingError(f"{sub_id}: source field {source} is not in the copybook")
            occurs.add(layout.field(source).occurs)
        sub = Rule(
            id=sub_id,
            target=f"{target}.{name}",
            sources=(source,),
            steps=tuple(_normalize_step(sub_id, s) for s in spec.get("steps") or []),
            checks=tuple(_normalize_check(sub_id, c) for c in spec.get("checks") or []),
        )
        if any(op in ARRAY_CHECKS or op == "unique" for op, _ in sub.checks):
            raise MappingError(f"{sub_id}: array and dataset checks belong on the parent rule")
        items.append((str(name), sub))
    if layout is not None and (len(occurs) != 1 or occurs.pop() < 2):
        raise MappingError(f"{rule_id}: item sources must be OCCURS fields with the same count")
    return tuple(items)


def mapping_from_dict(data: Dict[str, Any], layout: Optional[Layout] = None) -> Mapping:
    if not isinstance(data, dict) or not isinstance(data.get("rules"), list) or not data["rules"]:
        raise MappingError("Mapping must contain a non-empty 'rules' list")
    rules: List[Rule] = []
    ids, targets = set(), set()
    for index, raw in enumerate(data["rules"], start=1):
        if not isinstance(raw, dict):
            raise MappingError(f"Rule #{index} must be a mapping")
        rule_id = str(raw.get("id") or f"R{index}")
        if rule_id in ids:
            raise MappingError(f"Duplicate rule id {rule_id}")
        if not raw.get("target"):
            raise MappingError(f"{rule_id}: missing 'target'")
        target = str(raw["target"])
        if target in targets:
            raise MappingError(f"{rule_id}: target {target} is mapped twice")

        items: Tuple[Tuple[str, Rule], ...] = ()
        source = raw.get("source")
        if raw.get("items") is not None:
            items = _parse_items(rule_id, target, raw["items"], layout)
            sources = ()
        elif source is None:
            if "value" not in raw:
                raise MappingError(f"{rule_id}: needs a 'source' field or a constant 'value'")
            sources: Tuple[str, ...] = ()
        else:
            sources = tuple(str(s).upper() for s in _as_list(source))
            if not sources:
                raise MappingError(f"{rule_id}: 'source' is empty")
        if layout is not None:
            for name in sources:
                if name not in layout.names():
                    raise MappingError(f"{rule_id}: source field {name} is not in the copybook")
            if len(sources) > 1 and any(layout.field(s).occurs > 1 for s in sources):
                raise MappingError(f"{rule_id}: OCCURS fields cannot be concatenated")

        steps = raw.get("steps") or []
        checks = raw.get("checks") or []
        if not isinstance(steps, list) or not isinstance(checks, list):
            raise MappingError(f"{rule_id}: 'steps' and 'checks' must be lists")
        on_error = str(raw.get("on_error", "fail"))
        if on_error not in ("fail", "reject"):
            raise MappingError(f"{rule_id}: on_error must be 'fail' or 'reject'")

        checks_parsed = tuple(_normalize_check(rule_id, c) for c in checks)
        is_array = bool(items) or (
            layout is not None and len(sources) == 1 and layout.field(sources[0]).occurs > 1
        )
        if layout is not None and not is_array:
            bad = [op for op, _ in checks_parsed if op in ARRAY_CHECKS]
            if bad or raw.get("distinct"):
                raise MappingError(f"{rule_id}: {bad or 'distinct'} only applies to array rules")

        ids.add(rule_id)
        targets.add(target)
        rules.append(
            Rule(
                id=rule_id,
                target=target,
                sources=sources,
                steps=tuple(_normalize_step(rule_id, s) for s in steps),
                checks=checks_parsed,
                drop_blank=bool(raw.get("drop_blank", False)),
                distinct=bool(raw.get("distinct", False)),
                items=items,
                value=raw.get("value"),
                separator=str(raw.get("separator", "")),
                trim_parts=bool(raw.get("trim", True)),
                when=_condition(rule_id, raw["when"], layout) if raw.get("when") else None,
                when_else=raw.get("else"),
                on_error=on_error,
            )
        )

    key = data.get("key")
    if key is not None:
        key = str(key)
        if key not in ids:
            raise MappingError(f"key {key!r} is not a rule id")
        key_rule = next(r for r in rules if r.id == key)
        if key_rule.source is None:
            raise MappingError(f"key rule {key} must read exactly one source field")
        if layout is not None and layout.field(key_rule.source).occurs > 1:
            raise MappingError(f"key rule {key} cannot read an OCCURS field")
    record_filter = _condition("filter", data["filter"], layout) if data.get("filter") else None
    return Mapping(
        name=str(data.get("name") or "mapping"), rules=tuple(rules), key=key, filter=record_filter
    )


class _SpecLoader(yaml.SafeLoader):
    """YAML loader where only true/false are booleans (YAML 1.2 style).

    Plain YAML 1.1 turns codes such as NO (Norway), YES, ON and OFF into booleans,
    which silently corrupts lookup tables and allowed-value lists.
    """


_SpecLoader.yaml_implicit_resolvers = {
    first: [(tag, regexp) for tag, regexp in resolvers if tag != "tag:yaml.org,2002:bool"]
    for first, resolvers in yaml.SafeLoader.yaml_implicit_resolvers.items()
}
_SpecLoader.add_implicit_resolver(
    "tag:yaml.org,2002:bool", re.compile(r"^(?:true|True|TRUE|false|False|FALSE)$"), list("tTfF")
)


def load_mapping(path, layout: Optional[Layout] = None) -> Mapping:
    data = yaml.load(Path(path).read_text(encoding="utf-8"), Loader=_SpecLoader)  # noqa: S506
    return mapping_from_dict(data, layout)


# --------------------------------------------------------------------------- reference engine


class RuleRejected(Exception):
    """A rule with on_error: reject could not transform its input."""


def _is_blank(value: Any) -> bool:
    return value is None or (isinstance(value, str) and not value.strip())


def _norm(value: Any) -> str:
    return value.strip() if isinstance(value, str) else ("" if value is None else str(value))


def _equal(a: Any, b: Any) -> bool:
    try:
        return Decimal(_norm(a)) == Decimal(_norm(b))
    except Exception:
        return _norm(a) == _norm(b)


def condition_matches(record: Dict[str, Any], condition: Condition) -> bool:
    value = record[condition.field]
    if condition.op == "equals":
        result = _equal(value, condition.values[0])
    elif condition.op == "in":
        result = any(_equal(value, v) for v in condition.values)
    elif condition.op == "not_blank":
        result = not _is_blank(value)
    else:
        result = _is_blank(value)
    return not result if condition.negate else result


def _arith(value: Any, fn) -> Any:
    if _is_blank(value):
        return None
    was_float = isinstance(value, float)
    was_int = isinstance(value, int) and not isinstance(value, bool)
    result = fn(Decimal(str(value).strip()))
    if was_float:
        return float(result)
    if was_int:
        return int(result) if result == result.to_integral_value() else float(result)
    return result


def apply_step(value: Any, op: str, arg: Any, field: Optional[Field]) -> Any:
    if op in ("strip", "rstrip", "lstrip", "upper", "lower"):
        return getattr(value, op)() if isinstance(value, str) else value
    if op == "null_if_blank":
        return None if _is_blank(value) else value
    if op == "number":
        if _is_blank(value):
            return None
        number = Decimal(value.strip() if isinstance(value, str) else str(value))
        if field is not None and field.is_numeric and field.scale > 0:
            return float(number)
        return int(number) if number == number.to_integral_value() else float(number)
    if op == "date":
        if _is_blank(value) or _norm(value) in arg["nulls"]:
            return None
        return datetime.strptime(_norm(value), arg["in"]).strftime(arg["out"])
    if op == "map":
        return arg["values"].get(_norm(value), arg["default"])
    if op == "default":
        return arg if value is None else value
    if op == "substring":
        if not isinstance(value, str):
            return value
        start = arg["start"] - 1
        return value[start : start + arg["length"]]
    if op == "lstrip_zeros":
        if not isinstance(value, str):
            return value
        stripped = value.lstrip("0")
        return "0" if value and not stripped else stripped
    if op == "pad":
        if value is None:
            return None
        text = str(value)
        if arg["side"] == "left":
            return text.rjust(arg["length"], arg["char"])
        return text.ljust(arg["length"], arg["char"])
    if op == "boolean":
        key = _norm(value)
        if key in arg["true"]:
            return True
        if key in arg["false"]:
            return False
        return arg["default"]
    if op == "multiply":
        return _arith(value, lambda d: d * arg)
    if op == "divide":
        return _arith(value, lambda d: d / arg)
    if op == "round":
        return _arith(value, lambda d: d.quantize(Decimal(1).scaleb(-arg), rounding=ROUND_HALF_UP))
    if op == "replace":
        return None if value is None else re.sub(arg["pattern"], arg["with"], str(value))
    if op == "_truncate":
        return value[:arg] if isinstance(value, str) else value
    if op == "_abs":
        return abs(value) if isinstance(value, (Decimal, int, float)) else value
    if op == "_blank_as_empty":
        return "" if value is None else value
    raise MappingError(f"Unknown step {op}")


def check_passes(value: Any, op: str, arg: Any) -> bool:
    """True when ``value`` satisfies one check. Only ``required`` fails on a null."""
    if op == "required":
        return not _is_blank(value)
    if _is_blank(value):
        return True
    if op == "min_length":
        return len(str(value)) >= arg
    if op == "max_length":
        return len(str(value)) <= arg
    if op in ("min", "max"):
        try:
            number = Decimal(str(value).strip())
        except Exception:
            return False
        return number >= arg if op == "min" else number <= arg
    if op == "pattern":
        return re.fullmatch(str(arg), str(value)) is not None
    if op in ("unique", "min_items", "max_items", "unique_items"):
        return True  # evaluated on arrays or across records
    if op == "allowed":
        return any(_equal(value, a) if not isinstance(value, bool) else value == a for a in arg)
    raise MappingError(f"Unknown check {op}")


def _run_steps(value: Any, rule: Rule, field: Optional[Field]) -> Any:
    for op, arg in rule.steps:
        value = apply_step(value, op, arg, field)
    return value


def _transform(value: Any, rule: Rule, field: Optional[Field]) -> Any:
    try:
        return _run_steps(value, rule, field)
    except Exception:
        if rule.on_error == "reject":
            raise RuleRejected(rule.id)
        if rule.on_error == "null":
            return None
        raise


def _identity(value: Any) -> str:
    return repr(sorted(value.items())) if isinstance(value, dict) else repr(value)


def _dedupe(values: List[Any]) -> List[Any]:
    seen, out = set(), []
    for value in values:
        key = _identity(value)
        if key not in seen:
            seen.add(key)
            out.append(value)
    return out


def _finish_array(rule: Rule, items: List[Any], blank) -> List[Any]:
    if rule.drop_blank:
        items = [item for item in items if not blank(item)]
    if rule.distinct:
        items = _dedupe(items)
    if rule.array_op == "drop_last":
        items = items[:-1]
    elif rule.array_op == "first_only":
        items = items[:1]
    return items


def _failed_checks(rule: Rule, value: Any) -> List[str]:
    if isinstance(value, list):
        failed = []
        for op, arg in rule.checks:
            if op == "required":
                ok = bool(value)
            elif op == "min_items":
                ok = len(value) >= arg
            elif op == "max_items":
                ok = len(value) <= arg
            elif op == "unique_items":
                ok = len({_identity(v) for v in value}) == len(value)
            else:
                ok = all(check_passes(item, op, arg) for item in value)
            if not ok:
                failed.append(f"{rule.id}:{op}")
        return failed
    return [f"{rule.id}:{op}" for op, arg in rule.checks if not check_passes(value, op, arg)]


def evaluate_rule(record: Dict[str, Any], rule: Rule, layout: Layout) -> Tuple[Any, List[str]]:
    """Return (output value, failed check ids). Raises RuleRejected for rejected input."""
    if rule.when is not None and not condition_matches(record, rule.when):
        return rule.when_else, []

    if rule.items:
        return _evaluate_items(record, rule, layout)
    if rule.is_constant:
        value: Any = _transform(rule.value, rule, None)
    elif rule.is_concat:
        parts = [_norm(record[s]) if rule.trim_parts else str(record[s]) for s in rule.sources]
        if rule.parts_op == "reverse":
            parts = parts[::-1]
        elif rule.parts_op == "drop_last":
            parts = parts[:-1]
        value = _transform(rule.separator.join(parts), rule, None)
    else:
        field = layout.field(rule.source)
        raw = record[rule.source]
        if field.occurs > 1:
            count = len(raw)
            items = [_transform(raw[(i + rule.shift) % count], rule, field) for i in range(count)]
            value = _finish_array(rule, items, lambda v: v in (None, ""))
        else:
            value = _transform(raw, rule, field)
    return value, _failed_checks(rule, value)


def _evaluate_items(record: Dict[str, Any], rule: Rule, layout: Layout) -> Tuple[Any, List[str]]:
    count = layout.field(rule.items[0][1].source).occurs
    objects: List[Dict[str, Any]] = []
    failed: List[str] = []
    members = [
        (name, replace(sub, on_error=rule.on_error), layout.field(sub.source))
        for name, sub in rule.items
    ]
    for index in range(count):
        obj: Dict[str, Any] = {}
        for name, sub, field in members:
            raw = record[sub.source][(index + sub.shift) % count]
            obj[name] = _transform(raw, sub, field)
        objects.append(obj)
    objects = _finish_array(rule, objects, lambda o: all(v in (None, "") for v in o.values()))
    for obj in objects:
        for name, sub in rule.items:
            failed.extend(_failed_checks(sub, obj[name]))
    failed.extend(_failed_checks(rule, objects))
    return objects, sorted(set(failed))


def _set_path(doc: Dict[str, Any], path: str, value: Any) -> None:
    node = doc
    parts = path.split(".")
    for part in parts[:-1]:
        child = node.setdefault(part, {})
        if not isinstance(child, dict):
            raise MappingError(f"Target path {path} collides with a value at {part}")
        node = child
    if parts[-1] in node:
        raise MappingError(f"Target path {path} is written twice")
    node[parts[-1]] = value


def get_path(doc: Dict[str, Any], path: str, default: Any = None) -> Any:
    node: Any = doc
    for part in path.split("."):
        if not isinstance(node, dict) or part not in node:
            return default
        node = node[part]
    return node


Outcome = Tuple[bool, Any, List[str]]  # (input accepted, value, failed check ids)


def rule_outcome(record: Dict[str, Any], rule: Rule, layout: Layout) -> Outcome:
    """Evaluate one rule. Unexpected errors propagate (they are pipeline crashes)."""
    try:
        value, failed = evaluate_rule(record, rule, layout)
    except RuleRejected:
        return False, None, [f"{rule.id}:invalid"]
    return True, value, failed


def assemble(mapping: Mapping, outcomes: Dict[str, Outcome], filtered: bool) -> Dict[str, Any]:
    """Build the output document (or marker) from per-rule outcomes."""
    key_rule = mapping.key_rule

    def marker(doc: Dict[str, Any]) -> Dict[str, Any]:
        if key_rule is not None and outcomes[key_rule.id][0]:
            _set_path(doc, key_rule.target, outcomes[key_rule.id][1])
        return doc

    if filtered:
        return marker({FILTERED: True})
    doc: Dict[str, Any] = {}
    reasons: List[str] = []
    for rule in mapping.rules:
        accepted, value, failed = outcomes[rule.id]
        reasons.extend(failed)
        if accepted:
            _set_path(doc, rule.target, value)
    if reasons:
        return marker({REJECTED: sorted(reasons)})
    return doc


def is_filtered(record: Dict[str, Any], mapping: Mapping) -> bool:
    return mapping.filter is not None and not condition_matches(record, mapping.filter)


def apply_mapping(record: Dict[str, Any], mapping: Mapping, layout: Layout) -> Dict[str, Any]:
    """Transform one decoded source record into a target document.

    Returns the document, or a marker document:
      ``{"__filtered__": true, <key>}``           record is excluded by the mapping filter
      ``{"__rejected__": ["R2:required"], <key>}`` record fails a validation
    """
    filtered = is_filtered(record, mapping)
    if filtered:
        rules = [mapping.key_rule] if mapping.key_rule else []
        outcomes = {}
        for rule in rules:
            try:
                outcomes[rule.id] = rule_outcome(record, rule, layout)
            except Exception:
                outcomes[rule.id] = (False, None, [])
        return assemble(mapping, outcomes, True)
    outcomes = {rule.id: rule_outcome(record, rule, layout) for rule in mapping.rules}
    return assemble(mapping, outcomes, False)

"""Parse COBOL copybooks into fixed-length record layouts.

Supported:
  * elementary items with PIC X / A / 9, including S (sign) and V (implied decimal)
  * USAGE DISPLAY (zoned decimal), COMP-3 / PACKED-DECIMAL, and binary
    COMP / COMP-4 / COMP-5 / BINARY (big-endian, up to 18 digits)
  * OCCURS n TIMES on elementary items
  * level-88 condition names (ignored, they occupy no storage)

Not yet supported (raises CopybookError so a layout is never silently misread):
  REDEFINES, OCCURS on group items, OCCURS DEPENDING ON, floating point
  COMP-1/COMP-2, and edited pictures.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, replace
from typing import Iterator, List, Tuple


class CopybookError(ValueError):
    """Raised when a copybook cannot be parsed into a supported layout."""


_REPEAT = re.compile(r"([XA9])\((\d+)\)")
_ENTRY = re.compile(r"^(\d{1,2})\s+([A-Z0-9][A-Z0-9-]*)(.*)$")
_PIC = re.compile(r"\bPIC(?:TURE)?\s+(?:IS\s+)?(\S+)")
_OCCURS = re.compile(r"\bOCCURS\s+(\d+)")
_PACKED = re.compile(r"\b(?:COMP-3|COMPUTATIONAL-3|PACKED-DECIMAL)\b")
_FLOAT = re.compile(r"\b(?:COMP-[12]|COMPUTATIONAL-[12])\b")
_BINARY = re.compile(r"\b(?:COMP|COMP-[45]|COMPUTATIONAL|COMPUTATIONAL-[45]|BINARY)\b")


@dataclass(frozen=True)
class Field:
    """One elementary item of a fixed-length record."""

    name: str
    kind: str  # "X" alphanumeric, "9" zoned decimal, "P" packed (COMP-3), "B" binary (COMP)
    int_digits: int  # for "X": the character length
    scale: int = 0
    signed: bool = False
    occurs: int = 1
    offset: int = 0
    little_endian: bool = False  # only set by the byte-order mutant

    @property
    def total_digits(self) -> int:
        return self.int_digits + self.scale

    @property
    def item_length(self) -> int:
        """Bytes used by one occurrence."""
        if self.kind == "X":
            return self.int_digits
        if self.kind == "9":
            return self.total_digits
        if self.kind == "B":
            return 2 if self.total_digits <= 4 else 4 if self.total_digits <= 9 else 8
        return self.total_digits // 2 + 1

    @property
    def length(self) -> int:
        """Bytes used by all occurrences."""
        return self.item_length * self.occurs

    @property
    def is_numeric(self) -> bool:
        return self.kind in ("9", "P", "B")

    def describe(self) -> str:
        if self.kind == "X":
            pic = f"X({self.int_digits})"
        else:
            pic = ("S" if self.signed else "") + f"9({self.int_digits})"
            if self.scale:
                pic += f"V9({self.scale})"
            if self.kind == "P":
                pic += " COMP-3"
            elif self.kind == "B":
                pic += " COMP"
        if self.occurs > 1:
            pic += f" OCCURS {self.occurs}"
        return pic


@dataclass(frozen=True)
class Layout:
    """An ordered set of fields describing one fixed-length record."""

    fields: Tuple[Field, ...]
    record_length: int

    def field(self, name: str) -> Field:
        for f in self.fields:
            if f.name == name:
                return f
        raise KeyError(name)

    def names(self) -> List[str]:
        return [f.name for f in self.fields]

    def with_field(self, name: str, **changes) -> "Layout":
        """Return a copy of the layout with one field changed (used by mutants)."""
        return Layout(
            tuple(replace(f, **changes) if f.name == name else f for f in self.fields),
            self.record_length,
        )


def _statements(text: str) -> Iterator[str]:
    lines = []
    for raw in text.splitlines():
        line = raw.rstrip()
        if re.match(r"^\d{6}", line):  # fixed-format sequence area
            line = line[6:]
        stripped = line.strip()
        if not stripped or stripped[0] in "*/":
            continue
        lines.append(stripped)
    joined = " ".join(lines).upper()
    for stmt in re.split(r"\.(?=\s|$)", joined):
        stmt = " ".join(stmt.split())
        if stmt:
            yield stmt


def _picture(name: str, pic: str, usage: str) -> Tuple[str, int, int, bool]:
    expanded = _REPEAT.sub(lambda m: m.group(1) * int(m.group(2)), pic)
    if expanded and set(expanded) <= {"X", "A"}:
        if usage != "9":
            raise CopybookError(f"{name}: COMP usage is only valid on numeric pictures")
        return "X", len(expanded), 0, False
    signed = expanded.startswith("S")
    body = expanded[1:] if signed else expanded
    if not body.replace("V", "") or set(body) - {"9", "V"} or body.count("V") > 1:
        raise CopybookError(f"{name}: unsupported picture clause {pic!r}")
    left, _, right = body.partition("V")
    if usage == "B" and len(left) + len(right) > 18:
        raise CopybookError(f"{name}: binary fields over 18 digits are not supported")
    return usage, len(left), len(right), signed


def parse_copybook(text: str) -> Layout:
    """Parse copybook source text into a Layout with byte offsets assigned."""
    fields: List[Field] = []
    offset = 0
    fillers = 0
    seen = set()
    for stmt in _statements(text):
        match = _ENTRY.match(stmt)
        if not match:
            raise CopybookError(f"Cannot parse copybook statement: {stmt!r}")
        level, name, rest = int(match.group(1)), match.group(2), match.group(3)
        words = rest.split()
        if level == 88:
            continue
        if level == 66 or "RENAMES" in words:
            raise CopybookError(f"{name}: RENAMES is not supported")
        if "REDEFINES" in words:
            raise CopybookError(f"{name}: REDEFINES is not supported yet")
        if "DEPENDING" in words:
            raise CopybookError(f"{name}: OCCURS DEPENDING ON is not supported yet")
        pic = _PIC.search(rest)
        occurs = _OCCURS.search(rest)
        if pic is None:
            if occurs:
                raise CopybookError(f"{name}: OCCURS on group items is not supported yet")
            continue  # group item, no storage of its own
        if _PACKED.search(rest):
            usage = "P"
        elif _FLOAT.search(rest):
            raise CopybookError(f"{name}: floating point COMP-1/COMP-2 is not supported yet")
        elif _BINARY.search(rest):
            usage = "B"
        else:
            usage = "9"
        kind, int_digits, scale, signed = _picture(name, pic.group(1), usage)
        if name == "FILLER":
            fillers += 1
            name = f"FILLER-{fillers}"
        if name in seen:
            raise CopybookError(f"Duplicate field name {name}")
        seen.add(name)
        field = Field(
            name=name,
            kind=kind,
            int_digits=int_digits,
            scale=scale,
            signed=signed,
            occurs=int(occurs.group(1)) if occurs else 1,
            offset=offset,
        )
        if field.occurs < 1:
            raise CopybookError(f"{name}: OCCURS must be at least 1")
        fields.append(field)
        offset += field.length
    if not fields:
        raise CopybookError("Copybook contains no elementary fields")
    return Layout(tuple(fields), offset)


def load_copybook(path) -> Layout:
    with open(path, "r", encoding="utf-8") as handle:
        return parse_copybook(handle.read())

"""Witness generation and minimization.

1. For every field, build candidate values from the rules that read it: the
   formats it must parse (dates, codes, booleans, numbers in text), the
   boundaries of its validations (lengths, ranges, patterns, allowed values),
   blanks, duplicates and element counts for arrays, and the values that switch
   conditions and filters on and off.
2. Build a valid baseline record (one that loads cleanly and exercises every
   conditional rule it can), plus one baseline per condition outcome, then vary
   one field at a time. Every candidate is valid for the copybook by
   construction, and the reference pipeline must accept, reject or filter it
   without crashing.
3. Run the reference pipeline and every mutant on every candidate. A candidate
   "kills" a mutant when the outputs differ.
4. Select the smallest set of candidates that kills every killable mutant
   (greedy set cover). Those are the witness records.
"""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass, field as dc_field
from datetime import date
from decimal import Decimal, InvalidOperation
from typing import Any, Dict, List, Optional, Sequence, Set

from . import regexgen
from .codec import CodecError, decode_record, encode_record
from .copybook import Field, Layout
from .mapping import (
    ARRAY_CHECKS, FILTERED, REJECTED, Condition, Mapping, Rule, apply_step, assemble,
    check_passes, condition_matches, is_filtered, rule_outcome,
)
from .mutants import Mutant, generate_mutants, output_quantum
from .pipeline import ERROR_KEY, canonical, is_error, run_pipeline

_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
_SAMPLE_DATES = (date(2024, 1, 31), date(2024, 3, 5), date(1999, 12, 9))


# --------------------------------------------------------------------------- field usage


@dataclass
class FieldUsage:
    rules: List[Rule] = dc_field(default_factory=list)  # rules (or object members) reading it alone
    conditions: List[Condition] = dc_field(default_factory=list)
    in_concat: bool = False


def field_usage(mapping: Mapping) -> Dict[str, FieldUsage]:
    usage: Dict[str, FieldUsage] = defaultdict(FieldUsage)
    if mapping.filter is not None:
        usage[mapping.filter.field].conditions.append(mapping.filter)
    for rule in mapping.rules:
        if rule.when is not None:
            usage[rule.when.field].conditions.append(rule.when)
        if rule.items:
            for _, sub in rule.items:
                usage[sub.source].rules.append(sub)
        elif rule.is_concat:
            for name in rule.sources:
                usage[name].in_concat = True
        elif rule.source:
            usage[rule.source].rules.append(rule)
    return usage


# --------------------------------------------------------------------------- candidate values


def _rotated_text(length: int, seed: int) -> str:
    shift = seed % len(_ALPHABET)
    letters = _ALPHABET[shift:] + _ALPHABET[:shift]
    return (letters * (length // len(letters) + 1))[:length]


def _digits(length: int, seed: int) -> str:
    return "".join(str((seed + i) % 9 + 1) for i in range(length))


def _numeric_pattern(field: Field, seed: int) -> Decimal:
    whole = _digits(field.int_digits, seed) or "0"
    frac = _digits(field.scale, seed + 4)
    return Decimal(f"{whole}.{frac}" if frac else whole)


def _dedupe(values: Sequence[Any]) -> List[Any]:
    seen, out = set(), []
    for value in values:
        key = repr(value)
        if key not in seen:
            seen.add(key)
            out.append(value)
    return out


def _arith_factor(rule: Rule) -> Decimal:
    factor = Decimal(1)
    for op, arg in rule.steps:
        if op == "multiply":
            factor *= arg
        elif op == "divide":
            factor /= arg
    return factor


def _value_ok(value: Any, field: Field, rules: Sequence[Rule]) -> bool:
    """Does a single value transform cleanly and pass every scalar check of its rules?"""
    for rule in rules:
        try:
            out = value
            for op, arg in rule.steps:
                out = apply_step(out, op, arg, field)
        except Exception:
            return False
        for op, arg in rule.checks:
            if op not in ARRAY_CHECKS and op != "required" and not check_passes(out, op, arg):
                return False
            if op == "required" and not check_passes(out, op, arg) and field.occurs == 1:
                return False
    return True


def _text_specials(size: int, usage: FieldUsage, seed: int, variant: int) -> List[str]:
    out: List[str] = []
    for rule in usage.rules:
        for op, arg in rule.steps:
            if op == "date":
                ordered = _SAMPLE_DATES[variant % 3:] + _SAMPLE_DATES[:variant % 3]
                out += [d.strftime(arg["in"]) for d in ordered] + list(arg["nulls"])
            elif op == "map":
                keys = list(arg["values"])
                out += keys[variant % len(keys):] + keys[:variant % len(keys)]
                out.append(_rotated_text(size, seed + 11))
            elif op == "boolean":
                out += arg["true"] + arg["false"] + ["?"]
            elif op == "lstrip_zeros":
                out += ["00" + _digits(max(1, size - 2), seed), "0" * size]
            elif op == "replace":
                sample = regexgen.matching(arg["pattern"], variant)
                if sample:
                    out += [sample, f"{_rotated_text(2, seed)}{sample}"]
            elif op == "number":
                out += [_digits(size, seed), "0" * (size - 1) + "7", "1"]
        factor = _arith_factor(rule)
        for op, arg in rule.checks:
            if op == "pattern":
                match = regexgen.matching(str(arg), variant)
                out += [m for m in (match, regexgen.matching(str(arg), variant + 1),
                                    regexgen.near_miss(str(arg), match)) if m]
            elif op == "allowed":
                values = [str(a) for a in arg]
                out += values[variant % len(values):] + values[:variant % len(values)]
                out.append(_rotated_text(min(size, 3), seed + 13))
            elif op in ("min_length", "max_length"):
                out += [_rotated_text(n, seed) for n in (arg, arg - 1, arg + 1) if 0 < n <= size]
            elif op in ("min", "max") and any(o == "number" for o, _ in rule.steps):
                bound = arg / factor if factor else arg
                for value in (bound, bound - 1, bound + 1):
                    if value >= 0 and value == value.to_integral_value():
                        out.append(str(int(value)).zfill(size))
        ops = [op for op, _ in rule.steps]
        if "upper" in ops:
            out += [v.lower() for v in out if v.lower() != v]
        if "lower" in ops:
            out += [v.upper() for v in out if v.upper() != v]
    for condition in usage.conditions:
        out += [str(v) for v in condition.values] + [""]
    return out


def _numeric_specials(field: Field, usage: FieldUsage, quantum: Decimal) -> List[Decimal]:
    out: List[Decimal] = []
    for rule in usage.rules:
        factor = _arith_factor(rule)
        step = output_quantum(rule, field)
        for op, arg in rule.checks:
            if op in ("min", "max"):
                for target in (arg, arg - step, arg + step, arg - step / 2, arg + step / 2):
                    try:
                        out.append((target / factor).quantize(quantum))
                    except InvalidOperation:
                        continue
            elif op == "allowed":
                out += [Decimal(str(a)) for a in arg if _is_number(a)]
        for op, arg in rule.steps:
            if op in ("map", "boolean"):
                keys = list(arg["values"]) if op == "map" else arg["true"] + arg["false"]
                out += [Decimal(k) for k in keys if _is_number(k)]
    for condition in usage.conditions:
        out += [Decimal(str(v)) for v in condition.values if _is_number(v)]
    return out


def _is_number(value: Any) -> bool:
    try:
        Decimal(str(value))
        return True
    except InvalidOperation:
        return False


def item_candidates(field: Field, usage: FieldUsage, seed: int, variant: int = 0) -> List[Any]:
    """Candidate values for one occurrence of a field; the first is the preferred value."""
    if field.kind == "X":
        size = field.item_length
        primary = _rotated_text(size, seed)
        generic = [primary, primary.lower(), _rotated_text(max(1, size // 2), seed + 7), ""]
        values = [v for v in _dedupe(_text_specials(size, usage, seed, variant) + generic)
                  if len(v) <= size]
    else:
        quantum = Decimal(1).scaleb(-field.scale)
        largest = Decimal(10) ** field.int_digits - quantum
        pattern = _numeric_pattern(field, seed)
        generic = [pattern, Decimal(0), Decimal(1) if field.int_digits else quantum, largest]
        if field.signed:
            generic.insert(1, -pattern)
        lowest = -largest if field.signed else Decimal(0)
        values = _dedupe(
            v.quantize(quantum)
            for v in _numeric_specials(field, usage, quantum) + generic
            if lowest <= v <= largest
        )
    valid = [v for v in values if _value_ok(v, field, usage.rules)]
    return _dedupe(valid[:1] + values) if valid else values


def array_structures(field: Field, usage: FieldUsage, seed: int) -> List[List[Any]]:
    """Element layouts for an OCCURS field, always in the same order and count:
    all filled, last blank, every shorter element count, duplicates, duplicate across a gap.
    Parallel OCCURS fields use the same index so their blanks and duplicates line up."""
    items = item_candidates(field, usage, seed)
    blank: Any = "" if field.kind == "X" else Decimal(0).quantize(Decimal(1).scaleb(-field.scale))
    distinct = _dedupe(
        item_candidates(field, usage, seed + 5 * (i + 1), variant=i)[0] for i in range(field.occurs)
    )
    while len(distinct) < field.occurs:  # pad with any other valid items
        extra = [v for v in items if v not in distinct and _value_ok(v, field, usage.rules)]
        distinct.append(extra[0] if extra else blank)
    n = field.occurs
    lists = [distinct, distinct[:-1] + [blank]]
    lists += [distinct[:k] + [blank] * (n - k) for k in range(n - 1)]  # every element count
    lists.append(([distinct[0], distinct[0]] + distinct[1:])[:n])  # adjacent duplicate
    lists.append(([distinct[0], blank, distinct[0]] + distinct[1:])[:n])  # duplicate across a gap
    return lists


def value_candidates(field: Field, usage: FieldUsage, seed: int) -> List[Any]:
    """Candidate values for a whole field (lists for OCCURS fields)."""
    items = item_candidates(field, usage, seed)
    if field.occurs == 1:
        return items
    lists = array_structures(field, usage, seed)
    lists += [[item] * field.occurs for item in items]
    return _dedupe(lists)


# --------------------------------------------------------------------------- pool


def _uniquify(field: Field, value: Any, index: int) -> Any:
    """Make a key value unique per record while keeping its shape (case, padding, sign)."""
    if field.kind == "X":
        core = str(value or "").rstrip()
        if not core.strip():
            return None  # blank keys are not usable
        tag = f"{index:03d}"
        if len(core) > len(tag):
            return core[: len(core) - len(tag)] + tag
        return (core + tag)[: field.item_length]
    return value + index if value >= 0 else value - index


@dataclass
class Candidate:
    record: Dict[str, Any]
    data: bytes
    expected: Dict[str, Any]
    kills: Set[str] = dc_field(default_factory=set)

    @property
    def outcome(self) -> str:
        if FILTERED in self.expected:
            return "filtered"
        if REJECTED in self.expected:
            return "rejected"
        return "loaded"


@dataclass
class ForgeResult:
    layout: Layout
    mapping: Mapping
    mutants: List[Mutant]
    witnesses: List[Candidate]
    survivors: List[Mutant]
    pool_size: int

    @property
    def killed(self) -> Set[str]:
        return set().union(*(w.kills for w in self.witnesses)) if self.witnesses else set()

    @property
    def score(self) -> float:
        return len(self.killed) / len(self.mutants) if self.mutants else 1.0


def _badness(record: Dict[str, Any], layout: Layout, mapping: Mapping) -> float:
    """Lower is better: loads cleanly and exercises as many conditional rules as possible."""
    try:
        data = encode_record(layout, record)
    except CodecError:
        return float("inf")
    doc = run_pipeline(data, layout, mapping)
    if is_error(doc):
        return 1e6
    if FILTERED in doc:
        return 1e4
    score = 100.0 * len(doc.get(REJECTED, []))
    score += sum(1 for r in mapping.rules if r.when is not None and not condition_matches(record, r.when))
    return score


def _repair(base: Dict[str, Any], candidates: Dict[str, List[Any]], layout: Layout,
            mapping: Mapping, fixed: Set[str]) -> Dict[str, Any]:
    best = dict(base)
    best_score = _badness(best, layout, mapping)
    for _ in range(3):
        improved = False
        for name, values in candidates.items():
            if name in fixed or best_score == 0:
                continue
            for value in values:
                trial = dict(best)
                trial[name] = value
                score = _badness(trial, layout, mapping)
                if score < best_score:
                    best, best_score, improved = trial, score, True
        if not improved:
            break
    return best


def _condition_bases(base, candidates, layout, mapping) -> List[Dict[str, Any]]:
    """One extra baseline per condition, with the condition's outcome flipped."""
    conditions = [r.when for r in mapping.rules if r.when is not None]
    if mapping.filter is not None:
        conditions.append(mapping.filter)
    bases = []
    for condition in conditions:
        current = condition_matches(base, condition)
        for value in candidates[condition.field]:
            trial = dict(base)
            trial[condition.field] = value
            if condition_matches(trial, condition) != current:
                bases.append(_repair(trial, candidates, layout, mapping, {condition.field}))
                break
    return bases


def build_pool(layout: Layout, mapping: Mapping) -> List[Candidate]:
    usage = field_usage(mapping)
    candidates = {
        f.name: value_candidates(f, usage[f.name], seed=index * 7)
        for index, f in enumerate(layout.fields)
    }
    base = _repair({n: v[0] for n, v in candidates.items()}, candidates, layout, mapping, set())
    bases = [base] + _condition_bases(base, candidates, layout, mapping)

    records: List[Dict[str, Any]] = list(bases)
    seeds = {f.name: index * 7 for index, f in enumerate(layout.fields)}
    for rule in mapping.rules:  # line up blanks and duplicates across object members
        if not rule.items:
            continue
        members = [sub.source for _, sub in rule.items]
        shapes = {m: array_structures(layout.field(m), usage[m], seeds[m]) for m in members}
        for start in bases:
            for index in range(len(shapes[members[0]])):
                variant = dict(start)
                for member in members:
                    variant[member] = shapes[member][index]
                records.append(variant)
    width = max(len(values) for values in candidates.values())
    for k in range(1, width):  # "rich" records that change every field at once
        records.append({name: values[k % len(values)] for name, values in candidates.items()})
    for start in bases:  # one-field variations of every baseline
        for name, values in candidates.items():
            for value in values:
                if value != start[name]:
                    variant = dict(start)
                    variant[name] = value
                    records.append(variant)

    key_field = layout.field(mapping.key_rule.source) if mapping.key_rule else None
    pool: List[Candidate] = []
    seen, used_keys = set(), set()
    blank_key_loaded = False
    for index, record in enumerate(records):
        blank_key = False
        if key_field is not None:
            record = dict(record)
            unique = _uniquify(key_field, record[key_field.name], index)
            if unique is None:  # blank keys are kept to exercise key validations
                unique, blank_key = "", True
            elif unique in used_keys:
                continue
            record[key_field.name] = unique
        try:
            data = encode_record(layout, record)
        except CodecError:
            continue
        if data in seen:
            continue
        expected = run_pipeline(data, layout, mapping)
        if is_error(expected):  # input the specification itself cannot handle
            continue
        loaded = FILTERED not in expected and REJECTED not in expected
        if blank_key and loaded:  # at most one loaded document may have a blank key
            if blank_key_loaded:
                continue
            blank_key_loaded = True
        seen.add(data)
        if key_field is not None and not blank_key:
            used_keys.add(record[key_field.name])
        pool.append(Candidate(decode_record(layout, data), data, expected))
    return pool


class _CachedRecord:
    """Per-rule outcomes of the specification for one record, reused across mutants.

    Mutants share every unchanged Rule object with the specification, so only rules
    that are not the identical object (and the filter) are evaluated again.
    """

    def __init__(self, record: Dict[str, Any], layout: Layout, mapping: Mapping):
        self.record, self.layout = record, layout
        self.outcomes: Dict[int, Any] = {}
        for rule in mapping.rules:
            self._outcome(rule)

    def _outcome(self, rule: Rule):
        key = id(rule)
        if key not in self.outcomes:
            try:
                self.outcomes[key] = (rule, rule_outcome(self.record, rule, self.layout))
            except Exception as exc:  # noqa: BLE001 - a crash is an observable outcome
                self.outcomes[key] = (rule, exc)
        return self.outcomes[key][1]

    def run(self, mapping: Mapping) -> Dict[str, Any]:
        try:
            filtered = is_filtered(self.record, mapping)
            rules = ([mapping.key_rule] if mapping.key_rule else []) if filtered else mapping.rules
            outcomes = {}
            for rule in rules:
                outcome = self._outcome(rule)
                if isinstance(outcome, Exception):
                    if filtered:  # the key is optional on a filtered marker
                        outcome = (False, None, [])
                    else:
                        raise outcome
                outcomes[rule.id] = outcome
            return assemble(mapping, outcomes, filtered)
        except Exception as exc:  # noqa: BLE001
            return {ERROR_KEY: type(exc).__name__}


def forge(layout: Layout, mapping: Mapping) -> ForgeResult:
    """Generate the minimal witness set for a copybook and mapping."""
    mutants = generate_mutants(layout, mapping)
    pool = build_pool(layout, mapping)
    for candidate in pool:
        reference = canonical(candidate.expected)
        cached = _CachedRecord(candidate.record, layout, mapping)
        for mutant in mutants:
            if mutant.layout is layout:  # same decoding: recompute only the changed rule
                output = cached.run(mutant.mapping)
            else:
                output = run_pipeline(candidate.data, mutant.layout, mutant.mapping)
            if canonical(output) != reference:
                candidate.kills.add(mutant.id)

    remaining = set().union(*(c.kills for c in pool)) if pool else set()
    selected: List[Candidate] = []
    while remaining:
        best = max(pool, key=lambda c: (len(c.kills & remaining), c.outcome == "loaded"))
        gained = best.kills & remaining
        if not gained:
            break
        selected.append(best)
        remaining -= gained

    killed = set().union(*(c.kills for c in selected)) if selected else set()
    survivors = [m for m in mutants if m.id not in killed]
    return ForgeResult(layout, mapping, mutants, selected, survivors, len(pool))

"""Check a real pipeline's output for the witness records against the specification.

What is checked:
  * every record that should load is present, and nothing else is loaded
  * records that should be rejected or filtered out are not loaded
  * (optional) the reject file holds exactly the records that should be rejected
  * duplicate output documents, and duplicate values for rules with a ``unique`` check
  * every field, array and nested object: values, types, missing or extra paths,
    item counts, missing, extra and duplicate items, item order
"""

from __future__ import annotations

import re
from collections import Counter
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

from .codec import split_records
from .copybook import Layout
from .mapping import FILTERED, REJECTED, Mapping, get_path
from .pipeline import json_ready, run_pipeline

_MISSING = object()


@dataclass
class Mismatch:
    record: Optional[int]
    path: str
    rule_id: Optional[str]
    expected: Any
    actual: Any
    detail: str = ""


@dataclass
class VerifyResult:
    records: int
    loaded: int = 0
    rejected: int = 0
    filtered: int = 0
    mismatches: List[Mismatch] = field(default_factory=list)
    problems: List[str] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        return not self.mismatches and not self.problems


def _same(expected: Any, actual: Any) -> bool:
    """Equal values of compatible types (12 == 12.0 is fine; "12" vs 12 or True vs 1 is not)."""
    if isinstance(expected, bool) or isinstance(actual, bool):
        return type(expected) is type(actual) and expected == actual
    if isinstance(expected, (int, float)) and isinstance(actual, (int, float)):
        return expected == actual
    return type(expected) is type(actual) and expected == actual


def _token(value: Any) -> str:
    return repr(sorted(value.items())) if isinstance(value, dict) else repr(value)


def _show(value: Any) -> Any:
    return "<missing>" if value is _MISSING else value


def _diff(expected: Any, actual: Any, path: str, out: List[Tuple[str, Any, Any, str]]) -> None:
    if isinstance(expected, dict) and isinstance(actual, dict):
        for key in sorted(set(expected) | set(actual)):
            _diff(expected.get(key, _MISSING), actual.get(key, _MISSING),
                  f"{path}.{key}" if path else key, out)
        return
    if isinstance(expected, list) and isinstance(actual, list):
        _diff_list(expected, actual, path, out)
        return
    if expected is _MISSING or actual is _MISSING:
        detail = "path missing from output" if actual is _MISSING else "unexpected path in output"
        out.append((path, _show(expected), _show(actual), detail))
    elif not _same(expected, actual):
        detail = "" if type(expected) is type(actual) else (
            f"type {type(expected).__name__} expected, got {type(actual).__name__}")
        out.append((path, expected, actual, detail))


def _diff_list(expected: list, actual: list, path: str, out) -> None:
    if len(expected) != len(actual):
        out.append((path, f"{len(expected)} items", f"{len(actual)} items", "item count differs"))
    if any(isinstance(v, (dict, list)) for v in expected + actual):
        for index in range(max(len(expected), len(actual))):
            e = expected[index] if index < len(expected) else _MISSING
            a = actual[index] if index < len(actual) else _MISSING
            if e is _MISSING or a is _MISSING:
                out.append((f"{path}[{index}]", _show(e), _show(a),
                            "item missing" if a is _MISSING else "unexpected item"))
            else:
                _diff(e, a, f"{path}[{index}]", out)
        return
    want, got = Counter(_token(v) for v in expected), Counter(_token(v) for v in actual)
    by_token = {_token(v): v for v in expected + actual}
    for token in sorted(set(want) | set(got)):
        if want[token] == got[token]:
            continue
        value = by_token[token]
        if got[token] > want[token] and want[token] > 0:
            detail = f"duplicate item: appears {got[token]} times, expected {want[token]}"
        elif got[token] > want[token]:
            detail = "unexpected item"
        else:
            detail = "item missing"
        out.append((path, f"{value!r} x{want[token]}", f"{value!r} x{got[token]}", detail))
    if want == got and [_token(v) for v in expected] != [_token(v) for v in actual]:
        out.append((path, expected, actual, "same items in a different order"))


def _rule_for(path: str, mapping: Mapping) -> Optional[str]:
    plain = re.sub(r"\[\d+\]", "", path)
    best, best_len = None, -1
    for rule in mapping.rules:
        if plain == rule.target or plain.startswith(rule.target + "."):
            rule_id = rule.id
            if rule.items and plain.startswith(rule.target + "."):
                member = plain[len(rule.target) + 1:].split(".")[0]
                if any(name == member for name, _ in rule.items):
                    rule_id = f"{rule.id}.{member}"
            if len(rule.target) > best_len:
                best, best_len = rule_id, len(rule.target)
    if best is None:  # a whole object is missing or extra: name the rules writing inside it
        inside = [r.id for r in mapping.rules if r.target.startswith(plain + ".")]
        if inside:
            return ",".join(inside)
    return best


def _compare(result: VerifyResult, mapping: Mapping, index: int, expected, actual) -> None:
    diffs: List[Tuple[str, Any, Any, str]] = []
    _diff(expected, actual, "", diffs)
    for path, e, a, detail in diffs:
        result.mismatches.append(Mismatch(index, path, _rule_for(path, mapping), e, a, detail))


def verify(
    layout: Layout,
    mapping: Mapping,
    data: bytes,
    actual_docs: List[Dict[str, Any]],
    key: Optional[str] = None,
    actual_rejects: Optional[List[Dict[str, Any]]] = None,
) -> VerifyResult:
    """Compare a pipeline's loaded documents (and optionally its rejects) with the specification.

    Documents are matched by the dotted ``key`` path (default: the target of the
    mapping's ``key`` rule), or by position when no key is available.
    """
    if key is None and mapping.key_rule is not None:
        key = mapping.key_rule.target
    records = split_records(layout, data)
    expected = [json_ready(run_pipeline(r, layout, mapping)) for r in records]
    loaded = [(i, e) for i, e in enumerate(expected) if REJECTED not in e and FILTERED not in e]
    rejected = [(i, e) for i, e in enumerate(expected) if REJECTED in e]
    filtered = [(i, e) for i, e in enumerate(expected) if FILTERED in e]
    result = VerifyResult(len(records), len(loaded), len(rejected), len(filtered))

    if key:
        index: Dict[str, List[Dict[str, Any]]] = {}
        for doc in actual_docs:
            index.setdefault(_token(get_path(doc, key, _MISSING)), []).append(doc)
        for token, docs in index.items():
            if len(docs) > 1:
                result.problems.append(
                    f"duplicate output: {key} = {get_path(docs[0], key, '<missing>')!r} "
                    f"appears {len(docs)} times")
        expected_tokens = set()
        for i, doc in loaded:
            token = _token(get_path(doc, key, _MISSING))
            expected_tokens.add(token)
            if token not in index:
                result.problems.append(
                    f"record {i}: document {key} = {get_path(doc, key)!r} is missing from the output")
            else:
                _compare(result, mapping, i, doc, index[token][0])
        for i, doc in rejected + filtered:
            token = _token(get_path(doc, key, _MISSING))
            if token in index and token not in expected_tokens:
                why = (f"rejected ({', '.join(doc[REJECTED])})" if REJECTED in doc
                       else "filtered out by the mapping filter")
                result.problems.append(
                    f"record {i}: {key} = {get_path(doc, key)!r} was loaded but should be {why}")
                expected_tokens.add(token)
        for token, docs in index.items():
            if token not in expected_tokens:
                result.problems.append(
                    f"unexpected document in output: {key} = {get_path(docs[0], key, '<missing>')!r}")
    else:
        if len(actual_docs) != len(loaded):
            result.problems.append(
                f"expected {len(loaded)} loaded documents ({len(rejected)} rejected, "
                f"{len(filtered)} filtered), got {len(actual_docs)}")
        want = Counter(_token(e) for _, e in loaded)
        got = Counter(_token(a) for a in actual_docs)
        for token, count in got.items():
            if count > max(want[token], 1):
                result.problems.append(f"duplicate output: the same document appears {count} times")
        for (i, e), a in zip(loaded, actual_docs):
            _compare(result, mapping, i, e, a)

    if actual_rejects is not None:
        if key:
            want_rejects = Counter(_token(get_path(e, key, _MISSING)) for _, e in rejected)
            got_rejects = Counter(_token(get_path(r, key, _MISSING)) for r in actual_rejects)
            for token in sorted(set(want_rejects) | set(got_rejects)):
                if want_rejects[token] != got_rejects[token]:
                    shown = token if token != repr(_MISSING) else "<no key>"
                    result.problems.append(
                        f"reject file: {key} = {shown} expected {want_rejects[token]} time(s), "
                        f"found {got_rejects[token]}")
        elif len(actual_rejects) != len(rejected):
            result.problems.append(
                f"reject file: expected {len(rejected)} rejected records, found {len(actual_rejects)}")

    for rule in mapping.rules:  # dataset-level uniqueness
        if not any(op == "unique" for op, _ in rule.checks):
            continue
        values = Counter(
            _token(v) for v in (get_path(d, rule.target, None) for d in actual_docs) if v is not None
        )
        for token, count in values.items():
            if count > 1:
                result.mismatches.append(Mismatch(
                    None, rule.target, rule.id, "unique values", f"{token} in {count} documents",
                    "duplicate value across records"))
    return result

"""Run the reference pipeline (decode -> map) and compare outputs."""

from __future__ import annotations

import json
from typing import Any, Dict

from .codec import decode_record
from .copybook import Layout
from .mapping import Mapping, apply_mapping

ERROR_KEY = "__error__"


def run_pipeline(data: bytes, layout: Layout, mapping: Mapping) -> Dict[str, Any]:
    """Decode a raw record and apply the mapping.

    Failures are returned as ``{"__error__": "<ExceptionType>"}`` rather than raised,
    so a mutant that crashes on an input counts as producing a different output.
    """
    try:
        return apply_mapping(decode_record(layout, data), mapping, layout)
    except Exception as exc:  # noqa: BLE001 - any failure is an observable difference
        return {ERROR_KEY: type(exc).__name__}


def map_record(record: Dict[str, Any], layout: Layout, mapping: Mapping) -> Dict[str, Any]:
    """Apply the mapping to an already decoded record, with the same error handling."""
    try:
        return apply_mapping(record, mapping, layout)
    except Exception as exc:  # noqa: BLE001
        return {ERROR_KEY: type(exc).__name__}


def is_error(doc: Dict[str, Any]) -> bool:
    return ERROR_KEY in doc


def canonical(doc: Any) -> str:
    """A type-aware canonical form, so 12.3 (float) and Decimal('12.30') differ."""
    return json.dumps(doc, sort_keys=True, default=repr)


def json_ready(value: Any) -> Any:
    """Convert Decimals and other non-JSON values into JSON-safe values."""
    return json.loads(json.dumps(value, default=str))

